function renderPersonalHistory(){const render=(list,root,attr,empty)=>{root.innerHTML=list.length?list.slice(0,8).map(r=>`<button type="button" class="you-history-item" ${attr}="${escapeHTML(r.id)}"><span><strong>${escapeHTML(r.name)}</strong><small>${escapeHTML(r.cuisine||'Your kitchen')} · ${Number(r.time)||30} min</small></span><b>Open →</b></button>`).join(''):`<p>${empty}</p>`};const recentRoot=document.querySelector('#recent-recipes-list'),labRoot=document.querySelector('#food-lab-history');if(recentRoot)render(recentRecipes,recentRoot,'data-history-recipe','Your recently opened recipes will appear here.');if(labRoot)render(foodLabHistory,labRoot,'data-history-recipe','Your invented dishes will be saved here.');}
