function allKitchenRecipes(){const rows=[...recipes,...veganRecipes,...recentRecipes,...foodLabHistory,...saved,...communityRecipes,...localCommunityRecipes];return [...new Map(rows.filter(r=>r&&r.id).map(r=>[r.id,r])).values()]}
function renderMealPlanner(){const select=document.querySelector('#meal-plan-recipe'),current=select.value,options=allKitchenRecipes();select.innerHTML='<option value="">Choose a recipe</option>'+options.map(r=>`<option value="${escapeHTML(r.id)}">${escapeHTML(r.name)}</option>`).join('');if(options.some(r=>r.id===current))select.value=current;const dateField=document.querySelector('#meal-plan-date');if(!dateField.value){const today=new Date();dateField.value=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`}document.querySelector('#meal-plan-list').innerHTML=mealPlan.length?[...mealPlan].sort((a,b)=>a.date.localeCompare(b.date)).map((entry,index)=>`<div class="meal-plan-item"><span><strong>${escapeHTML(entry.recipe.name)}</strong><small>${escapeHTML(entry.date)}</small></span><button type="button" data-remove-meal="${escapeHTML(entry.id)}" aria-label="Remove ${escapeHTML(entry.recipe.name)}">×</button></div>`).join(''):'<p>Your weekly plan is empty. Add a recipe to get started.</p>';renderShoppingList()}
function renderShoppingList(){const root=document.querySelector('#shopping-list');root.innerHTML=shoppingList.length?`<h3>Your shopping list</h3>${shoppingList.map(item=>`<label class="shopping-item"><input type="checkbox" data-shopping-item="${escapeHTML(item.id)}" ${item.checked?'checked':''} /><span>${escapeHTML(item.name)}</span></label>`).join('')}`:''}
function buildShoppingList(){const gathered=new Map();mealPlan.forEach(entry=>(entry.recipe.ingredients||[]).forEach(name=>{const key=String(name).trim().toLocaleLowerCase();if(key&&!gathered.has(key))gathered.set(key,{id:key,name:String(name).trim(),checked:false})}));shoppingList=[...gathered.values()];writeStorage('yourkitchen-shopping-list',JSON.stringify(shoppingList));renderShoppingList()}
const cloudKeys=['good-thyme-saved','yourkitchen-recent-searches','yourkitchen-recipe-history','yourkitchen-food-lab-history','yourkitchen-taste-profile','yourkitchen-chat','yourkitchen-meal-plan','yourkitchen-shopping-list','yourkitchen-game-score'];
async function initializeSupabase(){if(supabaseClient)return supabaseClient;const config=window.YOURKITCHEN_SUPABASE||{};if(!/^https:\/\//.test(config.url||'')||!config.publishableKey)return null;if(!supabaseModulePromise)supabaseModulePromise=import('https://esm.sh/@supabase/supabase-js@2');const {createClient}=await supabaseModulePromise;supabaseClient=createClient(config.url,config.publishableKey);const {data,error}=await supabaseClient.auth.getSession();if(error)throw error;authUser=data.session?.user||null;updateAccountAuthUI();if(authUser)await loadAndSyncKitchen();supabaseClient.auth.onAuthStateChange((_event,session)=>{authUser=session?.user||null;updateAccountAuthUI();if(authUser)setTimeout(()=>loadAndSyncKitchen().catch(error=>{document.querySelector('#account-status').textContent=`Signed in, but your kitchen did not sync: ${error.message}`}),0)});return supabaseClient}
function updateAccountAuthUI(){const status=document.querySelector('#account-status'),signout=document.querySelector('#account-signout'),signup=document.querySelector('#account-signup'),form=document.querySelector('#account-auth-form');if(authUser){status.textContent=`Signed in as ${authUser.email||'Your account'}. Your kitchen is syncing across your devices.`;signout.hidden=false;signup.hidden=true;form.hidden=true}else{status.textContent='You’re browsing as a guest. Your recipes, ideas, and preferences are saved on this device.';signout.hidden=true;signup.hidden=false}}
function localKitchenData(){return Object.fromEntries(cloudKeys.map(key=>[key,readStorage(key,key==='yourkitchen-taste-profile'?'{}':'[]')]).map(([key,value])=>{try{return[key,JSON.parse(value)]}catch{return[key,key==='yourkitchen-taste-profile'?{}:[]]}}))}
function mergeKitchenData(local,remote){const result={...local};for(const key of cloudKeys){const a=local[key],b=remote[key];if(Array.isArray(a)&&Array.isArray(b)){const signature=item=>item?.id||item?.query||`${item?.role||''}:${item?.content||''}:${item?.name||''}`;result[key]=[...b,...a].filter((item,index,list)=>list.findIndex(other=>signature(other)===signature(item))===index).slice(0,50)}else if(key==='yourkitchen-taste-profile'&&b&&typeof b==='object')result[key]={...a,...b,cuisines:[...new Set([...(a.cuisines||[]),...(b.cuisines||[])])]};else if(key==='yourkitchen-game-score')result[key]=Math.max(Number(a)||0,Number(b)||0);else if(b!==undefined)result[key]=b}return result}
async function loadAndSyncKitchen(){if(!supabaseClient||!authUser)return;const {data,error}=await supabaseClient.from('user_kitchens').select('data').eq('user_id',authUser.id).maybeSingle();if(error)throw error;const local=localKitchenData(),merged=mergeKitchenData(local,data?.data||{});cloudHydrating=true;try{for(const key of cloudKeys)if(merged[key]!==undefined)writeStorage(key,JSON.stringify(merged[key]))}finally{cloudHydrating=false}saved=loadSaved();recentSearches=loadRecentSearches();recentRecipes=loadPersonalList('yourkitchen-recipe-history');foodLabHistory=loadPersonalList('yourkitchen-food-lab-history');tasteProfile=loadTasteProfile();kitchenChat=loadPersonalList('yourkitchen-chat');gameScore=Number(readStorage('yourkitchen-game-score','0'))||0;renderSaved();renderPersonalHistory();renderTasteProfile();renderKitchenChat();document.querySelector('#game-score').textContent=gameScore;const {error:syncError}=await supabaseClient.from('user_kitchens').upsert({user_id:authUser.id,data:merged,updated_at:new Date().toISOString()},{onConflict:'user_id'});if(syncError)throw syncError}
function queueCloudSync(){if(!supabaseClient||!authUser)return;clearTimeout(cloudSyncTimer);cloudSyncTimer=setTimeout(async()=>{const {error}=await supabaseClient.from('user_kitchens').upsert({user_id:authUser.id,data:localKitchenData(),updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error)document.querySelector('#account-status').textContent='Your kitchen could not sync just now. Your device still has your saved data.'},700)}
async function signInOrCreate(email,password,mode){const client=await initializeSupabase();if(!client)throw new Error('Add your Supabase Project URL and Publishable key to supabase-config.js, run the SQL setup, then reload this page.');const result=mode==='signup'?await client.auth.signUp({email,password,options:{emailRedirectTo:`${location.origin}${location.pathname}#account`}}):await client.auth.signInWithPassword({email,password});if(result.error)throw result.error;if(mode==='signup'&&!result.data.session)document.querySelector('#account-status').textContent='Check your email for a confirmation link, then come back here to sign in.';else if(result.data.session)document.querySelector('#account-status').textContent=`Signed in as ${result.data.user.email||'Your account'}. Syncing your personal kitchen…`}
function loadRecentSearches(){try{const rows=JSON.parse(readStorage('yourkitchen-recent-searches','[]')),cutoff=Date.now()-30*86400000;const clean=Array.isArray(rows)?rows.filter(x=>x&&typeof x.query==='string'&&Number.isFinite(x.at)&&x.at>=cutoff&&x.at<=Date.now()).slice(0,20):[];writeStorage('yourkitchen-recent-searches',JSON.stringify(clean));return clean}catch{writeStorage('yourkitchen-recent-searches','[]');return []}}
function recordSearch(query){query=String(query||'').trim().replace(/\s+/g,' ').slice(0,60);if(query.length<2)return;recentSearches=recentSearches.filter(x=>x.query.toLowerCase()!==query.toLowerCase());recentSearches.unshift({query,at:Date.now()});recentSearches=recentSearches.slice(0,20);writeStorage('yourkitchen-recent-searches',JSON.stringify(recentSearches));renderForYou()}
function dailySeed(text){let hash=2166136261;for(const char of text)hash=Math.imul(hash^char.charCodeAt(0),16777619);return hash>>>0}
function localDateKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function scheduleDailyRefresh(){clearTimeout(dailyRefreshTimer);const now=new Date(),next=new Date(now.getFullYear(),now.getMonth(),now.getDate()+1,0,0,2);dailyRefreshTimer=setTimeout(()=>{renderForYou();scheduleDailyRefresh()},next-now)}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderRecipes(){
 renderDashboard();const query=document.querySelector('#recipe-query').value.trim().toLowerCase();
 let pool=cuisine==='all'?recipes.filter(r=>r.mood===mood):recipes.filter(r=>r.cuisine===cuisine);
 if(query){const matching=recipes.filter(r=>{const local=localizedRecipe(r);return (cuisine==='all'||r.cuisine===cuisine)&&`${r.cuisine} ${r.name} ${r.desc} ${r.ingredients.join(' ')} ${local.name} ${local.desc} ${local.ingredients.join(' ')}`.toLowerCase().includes(query)});if(matching.length)pool=matching;else if(cuisine==='all')toast(ui().notFound.replace('{q}',query).replace('{mood}',ui().moods[mood]))}
 if(query){pool.sort((a,b)=>Number(b.name.toLowerCase().includes(query))-Number(a.name.toLowerCase().includes(query)))}else pool=[...pool].sort(()=>Math.random()-.5);displayed=pool.slice(0,query?12:3);
 const matched=query&&recipes.some(r=>{const local=localizedRecipe(r);return (cuisine==='all'||r.cuisine===cuisine)&&`${r.cuisine} ${r.name} ${r.desc} ${r.ingredients.join(' ')} ${local.name} ${local.desc} ${local.ingredients.join(' ')}`.toLowerCase().includes(query)});
 document.querySelector('#results-title').textContent=matched?ui().forQuery.replace('{q}',query):(cuisine==='all'?ui().moods[mood]:`${cuisine} recipes`);
 document.querySelector('#recipe-grid').innerHTML=displayed.map(base=>{const r=localizedRecipe(base);return `<article class="recipe-card" data-recipe-id="${r.id}"><div class="recipe-photo ${r.accent}" data-open-recipe="${r.id}"><img class="recipe-img" src="${r.image}" alt="${escapeHTML(r.imageAlt)}" loading="lazy" /><a class="image-credit" href="${r.creditUrl}" target="_blank" rel="noopener noreferrer" aria-label="Photo source: ${escapeHTML(r.credit)}">Photo: ${escapeHTML(r.credit)} ↗</a><span class="recipe-time">◷ ${r.time} min</span></div><div class="recipe-content"><button class="recipe-title-button" data-open-recipe="${r.id}" type="button"><span class="recipe-kicker">${escapeHTML(r.cuisine)} · ${escapeHTML(r.tag)}</span><h3>${escapeHTML(r.name)}</h3><span class="view-recipe-hint">See the full recipe →</span></button><p class="recipe-desc">${escapeHTML(r.desc)}</p><div class="recipe-details"><div><h4>${ui().need}</h4><ul>${r.ingredients.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ul></div><div><h4>${ui().steps}</h4><ol>${r.steps.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ol></div></div><div class="recipe-actions"><button class="save-recipe" data-id="${r.id}">${ui().save}</button><button class="copy-recipe" data-id="${r.id}">${ui().copy}</button></div></div></article>`}).join('');
}
function renderDashboard(){document.querySelector('#dashboard-recipe-count').textContent=recipes.length;document.querySelector('#dashboard-saved-count').textContent=saved.length;document.querySelector('#dashboard-cuisine-count').textContent=new Set(recipes.map(r=>r.cuisine)).size}
function renderSaved(){document.querySelector('#saved-count').textContent=saved.length;document.querySelector('#bottom-saved-count').textContent=saved.length;document.querySelector('#saved-heading-count').textContent=`(${saved.length})`;document.querySelector('#clear-saved').hidden=!saved.length;renderDashboard();const list=document.querySelector('#saved-list');if(!saved.length){list.innerHTML=`<p class="empty-saved">${ui().empty}</p>`;renderForYou();return}list.innerHTML=saved.map((base,i)=>{const r=localizedRecipe(base);return `<div class="saved-item"><img class="brand-mark" src="assets/icon.svg" alt="" /><div class="saved-text"><strong>${escapeHTML(r.name)}</strong><small>${escapeHTML(r.tag)}</small></div><button class="copy-saved" data-index="${i}">${ui().copy}</button><button class="remove-saved" data-index="${i}">${ui().remove}</button></div>`}).join('');renderForYou()}
function renderForYou(){const day=localDateKey(),now=Date.now(),validSearches=recentSearches.filter(x=>now-x.at<30*86400000);let ranked=recipes.map(r=>{const title=String(r.name).toLowerCase(),details=`${r.cuisine} ${r.desc} ${r.ingredients.join(' ')}`.toLowerCase();let score=0;validSearches.forEach((entry,index)=>{const phrase=entry.query.toLowerCase(),tokens=phrase.split(/[^\p{L}\p{N}]+/u).filter(t=>t.length>1),recency=1/(1+index*.35),freshness=1/(1+Math.max(0,now-entry.at)/86400000*.08);if(title.includes(phrase))score+=34*recency*freshness;for(const token of tokens){if(title.includes(token))score+=8*recency*freshness;else if(details.includes(token))score+=3*recency*freshness}});return{recipe:r,score}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||dailySeed(`${day}:${a.recipe.id}`)-dailySeed(`${day}:${b.recipe.id}`));let pool;if(ranked.length){const max=ranked[0].score;pool=ranked.filter(x=>x.score>=max*.32).slice(0,12).map(x=>x.recipe)}else{const preferred=saved[0]?.cuisine;pool=preferred?recipes.filter(r=>r.cuisine===preferred):recipes.filter(r=>r.mood==='sweet');if(pool.length<8)pool=[...pool,...recipes.filter(r=>!pool.includes(r))]}if(!pool.length)pool=recipes;const offset=pool.length>1?dailySeed(`${day}:yourkitchen-daily-picks`)%pool.length:0;const picks=Array.from({length:Math.min(3,pool.length)},(_,i)=>pool[(offset+i)%pool.length]);document.querySelector('#clear-search-history').hidden=!validSearches.length;const note=document.querySelector('.personal-note');note.textContent=validSearches.length?`Inspired by your recent searches: ${validSearches.slice(0,3).map(x=>x.query).join(' · ')}. Your picks refresh each day.`:'Search for dishes or ingredients and we’ll tailor these picks. They refresh each day.';document.querySelector('#for-you-grid').innerHTML=picks.map(r=>`<article class="personal-card"><img src="${r.image}" alt="" loading="lazy" /><div><small>${escapeHTML(r.cuisine)} · ${r.time} min</small><h3>${escapeHTML(r.name)}</h3><p>${escapeHTML(r.desc)}</p><button type="button" data-for-you-id="${r.id}">Open recipe →</button></div></article>`).join('')}
const renderForYouWithoutProfile=renderForYou;
renderForYou=function(){renderForYouWithoutProfile();const favorites=tasteProfile.cuisines||[];if(!favorites.length)return;let pool=recipes.filter(r=>favorites.includes(r.cuisine));if(tasteProfile.spice==='mild')pool=pool.filter(r=>r.mood!=='spicy');if(tasteProfile.spice==='hot')pool.sort((a,b)=>Number(b.mood==='spicy')-Number(a.mood==='spicy'));if(!pool.length)return;const day=localDateKey(),offset=dailySeed(`${day}:${favorites.join(',')}`)%pool.length,picks=Array.from({length:Math.min(3,pool.length)},(_,i)=>pool[(offset+i)%pool.length]);document.querySelector('.personal-note').textContent=`A daily mix based on the cuisines and spice level you picked: ${favorites.join(' · ')} · ${tasteProfile.spice==='any'?'any spice':tasteProfile.spice}.`;document.querySelector('#for-you-grid').innerHTML=picks.map(r=>`<article class="personal-card"><img src="${r.image}" alt="" loading="lazy" /><div><small>${escapeHTML(r.cuisine)} · ${r.time} min</small><h3>${escapeHTML(r.name)}</h3><p>${escapeHTML(r.desc)}</p><button type="button" data-for-you-id="${r.id}">Open recipe →</button></div></article>`).join('')};
function renderVeganRecipes(){document.querySelector('#vegan-count').textContent=veganRecipes.length;document.querySelector('#vegan-grid').innerHTML=veganRecipes.map(r=>`<article class="vegan-card"><button class="vegan-card-open" type="button" data-vegan-open="${r.id}"><img src="${r.image}" alt="${escapeHTML(r.imageAlt)}" loading="lazy" /><span class="vegan-card-copy"><small>${escapeHTML(r.cuisine)} · VEGAN · ${r.time} MIN</small><strong>${escapeHTML(r.name)}</strong><span>${escapeHTML(r.desc)}</span><b>See ingredients & steps →</b></span></button></article>`).join('')}
function renderCommunityRecipes(){const root=document.querySelector('#community-recipe-list'),cards=list=>list.map(r=>`<article class="community-recipe-card"><p>${escapeHTML(r.cuisine||'Community kitchen')} · ${Number(r.time)||30} min</p><h3>${escapeHTML(r.name)}</h3><small>${r.isLocal?'Saved on this device':'Shared by '+escapeHTML(r.author||'A home cook')}</small><button type="button" data-community-recipe="${escapeHTML(r.id)}">Open recipe →</button>${r.isLocal?'':`<p class="community-rating-summary">${r.ratingCount?`★ ${Number(r.ratingAverage).toFixed(1)} · ${r.ratingCount} ${r.ratingCount===1?'rating':'ratings'}`:'No ratings yet'}</p><form class="community-rating-form" data-rate-recipe="${escapeHTML(r.id)}"><label>Rate this recipe<select name="rating" required><option value="">Choose stars</option><option value="5">★★★★★ — Loved it</option><option value="4">★★★★ — Really good</option><option value="3">★★★ — It was okay</option><option value="2">★★ — Needs work</option><option value="1">★ — Not for me</option></select></label><textarea name="message" maxlength="300" placeholder="Optional note about how it turned out"></textarea><button type="submit">Share rating</button></form><button type="button" class="community-report-button" data-report-recipe="${escapeHTML(r.id)}">Report recipe</button><p class="community-review-status" data-review-status="${escapeHTML(r.id)}" role="status" aria-live="polite"></p>`}</article>`).join('');root.innerHTML=communityRecipes.length?cards(communityRecipes):'<div class="community-empty-box"><span aria-hidden="true">🍲</span><h3>No recipes shared by others yet</h3><p>You can be the first to add a favourite from your kitchen.</p><button type="button" data-start-sharing>Be the first to share ↗</button></div>';if(localCommunityRecipes.length)root.insertAdjacentHTML('beforeend',`<div class="community-local-box"><strong>Your device-only previews</strong><p>These recipes are saved on this device and haven’t been shared with others.</p><div class="community-recipe-list">${cards(localCommunityRecipes)}</div></div>`)}
async function loadCommunityFeed(){if(location.protocol==='file:')return;try{const response=await fetch('/api/community-recipes');const data=await response.json();if(!response.ok||!Array.isArray(data.recipes))throw new Error(data.error||'Could not load shared recipes.');communityRecipes=data.recipes;writeStorage('yourkitchen-community-recipes',JSON.stringify([...communityRecipes,...localCommunityRecipes]));renderCommunityRecipes();document.querySelector('#community-recipe-status').textContent='These recipes are shared with the YourKitchen community.'}catch{document.querySelector('#community-recipe-status').textContent='The shared feed is temporarily unavailable. Your device-only previews are still here.'}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2200)}
async function copyIngredients(r){const local=localizedRecipe(r);try{await navigator.clipboard.writeText(`${local.name}\n\n${local.ingredients.map(x=>'• '+x).join('\n')}`);toast(ui().copyOk)}catch{toast(ui().copyFail)}}
let activeRecipe=null;
function openRecipe(id){const base=recipes.find(r=>r.id===id)||veganRecipes.find(r=>r.id===id)||searchedRecipes.find(r=>r.id===id)||foodLabHistory.find(r=>r.id===id)||recentRecipes.find(r=>r.id===id)||communityRecipes.find(r=>r.id===id)||localCommunityRecipes.find(r=>r.id===id)||saved.find(r=>r.id===id);if(!base)return;rememberRecipe(base);activeRecipe=localizedRecipe(base);document.querySelector('#dialog-title').textContent=activeRecipe.name;document.querySelector('#dialog-save').textContent=saved.some(r=>r.id===id)?'✓ Saved':'＋ Save recipe';document.querySelector('#dialog-recipe').innerHTML=`<img src="${activeRecipe.image||'assets/recipes/tomato-soup.jpg'}" alt="${escapeHTML(activeRecipe.imageAlt||activeRecipe.name)}" /><p class="dialog-description">${escapeHTML(activeRecipe.desc||`Shared by ${activeRecipe.author||'a home cook'}.`)}</p><div class="dialog-columns"><section><h3>Ingredients</h3><ul>${activeRecipe.ingredients.map(item=>`<li>${escapeHTML(item)}</li>`).join('')}</ul></section><section><h3>Step by step</h3><ol>${activeRecipe.steps.map(step=>`<li>${escapeHTML(step)}</li>`).join('')}</ol></section></div>`;document.querySelector('#helper-answer').hidden=true;document.querySelector('#helper-answer').textContent='';document.querySelector('#helper-question').value='';const dialog=document.querySelector('#recipe-dialog');dialog.scrollTop=0;dialog.showModal()}
function offlineCookingAnswer(r,question){const q=question.toLowerCase();const times=r.steps.filter(s=>/\b\d+\s*(minutes?|mins?|hours?|°c|°f)\b/i.test(s));if(/how long|how much time|temperature|how hot|how many minutes/.test(q)){return `The recipe takes about ${r.time} minutes overall.${times.length?` In the steps: ${times.join(' ')}`:' Follow the doneness cues in each step, since the recipe does not give a separate oven temperature.'}`}if(/substitut|instead|replace|swap|allerg|cannot eat/.test(q)){return `The ingredients for this dish are ${r.ingredients.join(', ')}. Which ingredient would you like to replace? For allergies, check every product label and avoid ingredients you may react to.`}if(/spic|mild|hot|chili|chilli/.test(q)){const spice=r.ingredients.filter(i=>/chili|chilli|pepper|paprika|cumin|garam masala|curry/i.test(i));return spice.length?`The spice comes from ${spice.join(', ')}. You can start with less, taste, and add more near the end.`:'This recipe does not list chili or hot spice. Season gradually and taste as you cook.'}return `For ${r.name}, the steps are: ${r.steps.join(' ')} The listed ingredients are ${r.ingredients.join(', ')}. Ask me about a particular ingredient or step.`}
document.querySelector('#recipe-grid').addEventListener('click',e=>{if(e.target.closest('.image-credit'))return;const open=e.target.closest('[data-open-recipe]');if(open){e.preventDefault();openRecipe(open.dataset.openRecipe);return}const btn=e.target.closest('button');if(btn){const recipe=recipes.find(r=>r.id===btn.dataset.id);if(btn.classList.contains('copy-recipe'))copyIngredients(recipe);if(btn.classList.contains('save-recipe')){if(saved.some(x=>x.id===recipe.id)){toast(ui().already);return}saved.unshift(recipe);writeStorage('good-thyme-saved',JSON.stringify(saved));renderSaved();toast(ui().saveOk)}return}const card=e.target.closest('.recipe-card');if(card)openRecipe(card.dataset.recipeId)});
