document.querySelector('#ai-recipe-form').addEventListener('submit',async e=>{e.preventDefault();const prompt=document.querySelector('#ai-recipe-prompt').value.trim(),status=document.querySelector('#ai-recipe-status'),submit=e.currentTarget.querySelector('button'),results=document.querySelector('#ai-recipe-results');if(location.protocol==='file:'){status.textContent='OpenAI recipe generation needs the hosted website. Try “chocolate” in the recipe search for built-in dessert ideas.';return}submit.disabled=true;status.textContent='Cooking up a few ideas…';results.innerHTML='';try{const response=await fetch('/api/recipe-ideas',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt,language})});const data=await response.json();if(!response.ok||!Array.isArray(data.recipes))throw new Error(data.error||'Could not make recipe ideas');const generated=data.recipes.map((raw,i)=>{const name=String(raw.name||'AI recipe').slice(0,120),photo=/chocolate|brownie|cake|cookie|cocoa/i.test(name)?'cocoa-mug':/apple|fruit|berry|lemon|muffin/i.test(name)?'apple-crumble':/pasta|italian/i.test(`${name} ${raw.cuisine}`)?'lemon-pasta':/salad|hummus|falafel/i.test(name)?'chickpea-salad':/noodle|chinese/i.test(`${name} ${raw.cuisine}`)?'chili-noodles':'tomato-soup',moodNames=['cozy','fresh','spicy','quick','sweet'];return withPhoto(photo,{id:`ai-${Date.now()}-${i}`,name,cuisine:String(raw.cuisine||'AI pick').slice(0,40),mood:moodNames.includes(raw.mood)?raw.mood:'cozy',time:Math.max(5,Math.min(240,Number(raw.time)||30)),tag:'AI RECIPE IDEA',desc:String(raw.description||'A recipe idea made for you.').slice(0,300),ingredients:(Array.isArray(raw.ingredients)?raw.ingredients:[]).slice(0,20).map(x=>String(x).slice(0,160)),steps:(Array.isArray(raw.steps)?raw.steps:[]).slice(0,12).map(x=>String(x).slice(0,500))})});recipes.unshift(...generated);storePersonalList('yourkitchen-ai-recipes',[...generated,...loadPersonalList('yourkitchen-ai-recipes')]);renderDashboard();status.textContent='Here are three fresh ideas. Tap one to see all the steps.';const sourceLinks=(Array.isArray(data.sources)?data.sources:[]).filter(s=>/^https:\/\//.test(s.url)).slice(0,6);results.innerHTML=generated.map(r=>`<article class="ai-idea-card"><p>${escapeHTML(r.cuisine)} · ${r.time} min</p><h3>${escapeHTML(r.name)}</h3><p>${escapeHTML(r.desc)}</p><button type="button" data-ai-recipe-id="${r.id}">See recipe →</button></article>`).join('')+(sourceLinks.length?`<div class="ai-sources"><strong>Web sources:</strong> ${sourceLinks.map(s=>`<a href="${escapeHTML(s.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(s.title)} ↗</a>`).join(' · ')}</div>`:'')}catch(error){status.textContent=error.message||'AI recipes are not available right now. Try again in a little while.'}finally{submit.disabled=false}});
