async function searchWebRecipes(prompt,{vegan=false,status,results,button}={}){
 const clean=String(prompt||'').trim();if(!clean){status.textContent='Type a dish, ingredient, or craving first.';return}
 if(location.protocol==='file:'){status.textContent='Online recipe search works after the website is hosted. Built-in recipes remain available offline.';return}
 button.disabled=true;status.textContent=vegan?'Looking for plant-based recipes…':'Searching for matching recipes…';results.innerHTML='';
 try{const response=await fetch('/api/recipe-ideas',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:clean,language,dietary:vegan?'vegan':'any'})});const data=await response.json();if(!response.ok||!Array.isArray(data.recipes))throw new Error(data.error||'Could not find recipes');
  const allSources=Array.isArray(data.sources)?data.sources.filter(s=>/^https:\/\//.test(s.url)):[],moods=['cozy','fresh','spicy','quick','sweet'],stamp=Date.now();
  const generated=data.recipes.map((raw,i)=>{const name=String(raw.name||'Recipe idea').slice(0,120),photo=/chocolate|brownie|cake|cookie|cocoa/i.test(name)?'cocoa-mug':/apple|fruit|berry|lemon|muffin/i.test(name)?'apple-crumble':/pasta|italian/i.test(`${name} ${raw.cuisine}`)?'lemon-pasta':/salad|hummus|falafel/i.test(name)?'chickpea-salad':/noodle|chinese/i.test(`${name} ${raw.cuisine}`)?'chili-noodles':'tomato-soup',source=allSources.find(s=>s.url===raw.source_url);return withPhoto(photo,{id:`web-${stamp}-${i}`,name,cuisine:String(raw.cuisine||'Recipe pick').slice(0,40),mood:moods.includes(raw.mood)?raw.mood:'cozy',time:Math.max(5,Math.min(240,Number(raw.time)||30)),tag:vegan?'VEGAN · WEB RECIPE':'WEB RECIPE IDEA',desc:String(raw.description||'A recipe idea matched to your search.').slice(0,300),sourceUrl:source?.url||'',sourceName:source?.title||'',ingredients:(Array.isArray(raw.ingredients)?raw.ingredients:[]).slice(0,20).map(x=>String(x).slice(0,160)),steps:(Array.isArray(raw.steps)?raw.steps:[]).slice(0,12).map(x=>String(x).slice(0,500)),...(vegan?{vegan:true}:{})})});
  searchedRecipes=generated;if(results.id==='food-lab-results'){foodLabHistory=[...generated.map(r=>({...r,experimentPrompt:clean,createdAt:new Date().toISOString()})),...foodLabHistory].slice(0,30);storePersonalList('yourkitchen-food-lab-history',foodLabHistory);renderPersonalHistory()}status.textContent=`Found ${generated.length} matching recipes. Choose one for ingredients and step-by-step instructions.`;
  const usedDomains=new Set(),sources=allSources.filter(s=>{try{const host=new URL(s.url).hostname.replace(/^www\./,'').toLowerCase();if(usedDomains.has(host))return false;usedDomains.add(host);return true}catch{return false}}).slice(0,6);results.innerHTML=generated.map(r=>`<article class="ai-idea-card"><p>${escapeHTML(r.cuisine)} · ${r.time} min${vegan?' · VEGAN':''}</p><h3>${escapeHTML(r.name)}</h3><p>${escapeHTML(r.desc)}</p>${r.sourceUrl?`<a class="recipe-source-link" href="${escapeHTML(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">Full instructions at ${escapeHTML(r.sourceName||'the original site')} ↗</a>`:''}<button type="button" data-ai-recipe-id="${r.id}">Preview this idea →</button></article>`).join('')+(sources.length?`<div class="ai-sources"><strong>More recipe sites:</strong> ${sources.map(s=>`<a href="${escapeHTML(s.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(s.title)} ↗</a>`).join(' · ')}</div>`:'');
 }catch(error){status.textContent=error.message||'Recipe search is unavailable right now. Please try again.'}finally{button.disabled=false}
}
document.querySelector('#search-web-recipes').addEventListener('click',e=>searchWebRecipes(document.querySelector('#recipe-query').value,{status:document.querySelector('#web-recipe-status'),results:document.querySelector('#web-recipe-results'),button:e.currentTarget}));
document.querySelector('#vegan-search-form').addEventListener('submit',e=>{e.preventDefault();searchWebRecipes(document.querySelector('#vegan-recipe-query').value,{vegan:true,status:document.querySelector('#vegan-recipe-status'),results:document.querySelector('#vegan-web-results'),button:e.currentTarget.querySelector('button')})});
document.querySelector('#food-lab-form').addEventListener('submit',e=>{e.preventDefault();const prompt=`Invent creative dish ideas using these ingredients: ${document.querySelector('#food-lab-ingredients').value.trim()}. Flavor direction: ${document.querySelector('#food-lab-flavor').value}. Cooking style: ${document.querySelector('#food-lab-style').value}. Combine these thoughtfully and suggest practical substitutions if useful.`;searchWebRecipes(prompt,{vegan:document.querySelector('#food-lab-vegan').checked,status:document.querySelector('#food-lab-status'),results:document.querySelector('#food-lab-results'),button:e.currentTarget.querySelector('button')})});
document.querySelector('#community-recipe-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button'),status=document.querySelector('#community-recipe-status'),formData=new FormData(form),entry={name:String(formData.get('name')||'').trim(),cuisine:String(formData.get('cuisine')||'').trim()||'Community kitchen',time:Number(formData.get('time')),author:String(formData.get('author')||'').trim()||'A home cook',mood:'cozy',desc:'A recipe shared by a home cook.',ingredients:String(formData.get('ingredients')||'').split(/\r?\n/).map(s=>s.trim()).filter(Boolean),steps:String(formData.get('steps')||'').split(/\r?\n/).map(s=>s.trim()).filter(Boolean)};if(entry.ingredients.length<2||entry.steps.length<2){status.textContent='Please add at least two ingredients and two steps.';return}button.disabled=true;status.textContent='Sharing your recipe…';try{if(location.protocol==='file:')throw new Error('This preview is not connected to the community service.');const response=await fetch('/api/community-recipes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(entry)}),data=await response.json();if(!response.ok||!data.recipe)throw new Error(data.error||'Your recipe could not be shared.');communityRecipes=[data.recipe,...communityRecipes.filter(r=>r.id!==data.recipe.id)].slice(0,50);writeStorage('yourkitchen-community-recipes',JSON.stringify([...communityRecipes,...localCommunityRecipes]));renderCommunityRecipes();form.reset();form.elements.time.value='30';status.textContent='Your recipe is now in Recipes from other kitchens for everyone to enjoy.'}catch(error){status.textContent=`${error.message||'Could not share this recipe.'} Your recipe has been saved on this device.`;entry.id=`local-${Date.now()}`;entry.isLocal=true;entry.createdAt=new Date().toISOString();localCommunityRecipes.unshift(entry);localCommunityRecipes=localCommunityRecipes.slice(0,50);writeStorage('yourkitchen-community-recipes',JSON.stringify([...communityRecipes,...localCommunityRecipes]));renderCommunityRecipes()}finally{button.disabled=false}});
document.querySelector('#community-recipe-list').addEventListener('click',e=>{const share=e.target.closest('[data-start-sharing]');if(share){document.querySelector('#community-recipe-form').scrollIntoView({behavior:'smooth',block:'center'});document.querySelector('#community-recipe-form [name="name"]').focus({preventScroll:true});return}const button=e.target.closest('[data-community-recipe]');if(button)openRecipe(button.dataset.communityRecipe)});
document.querySelector('#community-recipe-list').addEventListener('submit',async e=>{const form=e.target.closest('[data-rate-recipe]');if(!form)return;e.preventDefault();const button=form.querySelector('button'),status=document.querySelector(`[data-review-status="${form.dataset.rateRecipe}"]`);button.disabled=true;status.textContent='Sending your rating…';try{const response=await fetch('/api/community-reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'rate',recipeId:form.dataset.rateRecipe,rating:Number(form.elements.rating.value),message:form.elements.message.value.trim()})}),data=await response.json();if(!response.ok||!data.saved)throw new Error(data.error||'Could not save this rating.');status.textContent='Thanks for rating this recipe!';form.reset();await loadCommunityFeed()}catch(error){status.textContent=location.protocol==='file:'?'Ratings are available once the hosted community service is connected.':error.message||'Could not save this rating.'}finally{button.disabled=false}});
document.querySelector('#community-recipe-list').addEventListener('click',async e=>{const report=e.target.closest('[data-report-recipe]');if(!report)return;const status=document.querySelector(`[data-review-status="${report.dataset.reportRecipe}"]`);report.disabled=true;status.textContent='Sending report…';try{const response=await fetch('/api/community-reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'report',recipeId:report.dataset.reportRecipe,message:'Reported by a community member for review.'})}),data=await response.json();if(!response.ok||!data.saved)throw new Error(data.error||'Could not report this recipe.');status.textContent='Thanks — your report was sent to the YourKitchen team for review.'}catch(error){status.textContent=location.protocol==='file:'?'Reports are available once the hosted community service is connected.':error.message||'Could not send this report.'}finally{report.disabled=false}});
function getDishReviews(){try{const list=JSON.parse(readStorage('yourkitchen-dish-feedback','[]'));return Array.isArray(list)?list:[]}catch{return []}}
function renderDishFeedback(recipe){const root=document.querySelector('#dialog-recipe'),entry=getDishReviews().find(item=>item.recipeId===recipe.id),section=document.createElement('section');section.className='dish-feedback';section.innerHTML='<h3>How was this dish?</h3><p>After you cook it, rate how it turned out and leave a note.</p><form id="dish-feedback-form"><label>Your rating<select name="rating" required><option value="">Choose a rating</option><option value="5">★★★★★ — Loved it</option><option value="4">★★★★ — Really good</option><option value="3">★★★ — It was okay</option><option value="2">★★ — Needs work</option><option value="1">★ — Not for me</option></select></label><label>Your cooking notes<textarea name="comment" maxlength="500" placeholder="What worked well? What would you change next time?"></textarea></label><button type="submit">Send dish feedback</button><p class="dish-feedback-status" role="status" aria-live="polite"></p></form>';root.append(section);if(entry){section.querySelector('[name="rating"]').value=String(entry.rating);section.querySelector('[name="comment"]').value=entry.message||'';section.querySelector('.dish-feedback-status').textContent='Your feedback for this dish was sent.'}}
function scaledAmount(line,servings){const factor=servings/2,match=String(line).match(/^(\s*)(\d+\/\d+|\d+(?:\.\d+)?|½|¼|¾)(?=\s)/);if(!match)return line;let value=match[2];const fractions={'½':.5,'¼':.25,'¾':.75};const number=fractions[value]??(value.includes('/')?Number(value.split('/')[0])/Number(value.split('/')[1]):Number(value));const scaled=Math.round(number*factor*4)/4;const whole=Math.floor(scaled),fraction=scaled-whole,token=(whole?String(whole):'')+(fraction===.25?'¼':fraction===.5?'½':fraction===.75?'¾':'');return line.replace(match[0],`${match[1]}${token||'0'}`)}
function renderCookMode(recipe){const root=document.querySelector('#dialog-recipe'),section=document.createElement('section');section.className='cook-mode-panel';section.innerHTML=`<div class="cook-mode-heading"><div><p class="eyebrow">COOK ALONG</p><h3>Cook mode</h3></div><button type="button" id="cook-mode-toggle">Start cooking</button></div><label class="servings-control">Servings <select id="cook-servings">${Array.from({length:8},(_,i)=>`<option value="${i+1}" ${i===1?'selected':''}>${i+1}</option>`).join('')}</select></label><p class="cook-ingredients-label">Scaled ingredients</p><ul class="scaled-ingredients">${recipe.ingredients.map(line=>`<li>${escapeHTML(line)}</li>`).join('')}</ul><div class="cook-mode-checklist" hidden><p>Tick each step as you go. Use the built-in timers where the recipe gives a time.</p><ol>${recipe.steps.map((step,index)=>{const minutes=Number(step.match(/\b(\d{1,3})\s*(?:minutes?|mins?)\b/i)?.[1])||0;return `<li><label><input type="checkbox" data-cook-step="${index}" /><span>${escapeHTML(step)}</span></label>${minutes?`<button type="button" class="step-timer" data-seconds="${minutes*60}">Start ${minutes} min timer</button>`:''}</li>`}).join('')}</ol><p class="cook-progress" role="status">0 of ${recipe.steps.length} steps done</p></div>`;root.append(section);section.querySelector('#cook-mode-toggle').addEventListener('click',e=>{const checklist=section.querySelector('.cook-mode-checklist');checklist.hidden=!checklist.hidden;e.currentTarget.textContent=checklist.hidden?'Start cooking':'Cook mode is on';if(!checklist.hidden)checklist.scrollIntoView({behavior:'smooth',block:'nearest'})});section.querySelector('#cook-servings').addEventListener('change',e=>{section.querySelectorAll('.scaled-ingredients li').forEach((li,index)=>li.textContent=scaledAmount(recipe.ingredients[index],Number(e.target.value)))});section.querySelector('.cook-mode-checklist').addEventListener('change',()=>{const done=section.querySelectorAll('[data-cook-step]:checked').length;section.querySelector('.cook-progress').textContent=`${done} of ${recipe.steps.length} steps done`});section.querySelector('.cook-mode-checklist').addEventListener('click',e=>{const button=e.target.closest('.step-timer');if(!button||button.dataset.running)return;let remaining=Number(button.dataset.seconds);button.dataset.running='true';button.disabled=true;const original=button.textContent;button.textContent=`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`;const timer=setInterval(()=>{remaining--;if(remaining<=0){clearInterval(timer);button.textContent='Timer done!';button.disabled=false;button.dataset.running='';toast('Your cooking timer is done!');return}button.textContent=`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`},1000);button.dataset.original=original})}
const openRecipeWithoutDishFeedback=openRecipe;openRecipe=function(id){openRecipeWithoutDishFeedback(id);if(activeRecipe){renderCookMode(activeRecipe);renderDishFeedback(activeRecipe)}};
function saveFeedbackLocally(entry){const pending=(()=>{try{const parsed=JSON.parse(readStorage('yourkitchen-feedback-outbox','[]'));return Array.isArray(parsed)?parsed:[]}catch{return []}})();pending.push({...entry,queuedAt:new Date().toISOString()});writeStorage('yourkitchen-feedback-outbox',JSON.stringify(pending.slice(-30)))}
async function deliverFeedback(entry,status){try{if(location.protocol==='file:')throw new Error('The website is not hosted yet.');const response=await fetch('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(entry)}),data=await response.json();if(!response.ok||!data.saved)throw new Error(data.error||'Could not send feedback.');status.textContent='Thank you — your feedback reached the YourKitchen team.';return true}catch(error){saveFeedbackLocally(entry);status.textContent=`Could not reach the feedback server. Saved on this device for now. ${error.message||''}`;return false}}
document.querySelector('#dialog-recipe').addEventListener('submit',async e=>{if(e.target.id!=='dish-feedback-form')return;e.preventDefault();const form=e.target,button=form.querySelector('button'),status=form.querySelector('.dish-feedback-status'),rating=Number(form.elements.rating.value),message=form.elements.comment.value.trim();button.disabled=true;status.textContent='Sending feedback…';const entry={kind:'dish',recipeId:activeRecipe.id,recipeName:activeRecipe.name,rating,message};const sent=await deliverFeedback(entry,status);if(sent){const list=getDishReviews().filter(item=>item.recipeId!==activeRecipe.id);list.push({recipeId:activeRecipe.id,rating,message});writeStorage('yourkitchen-dish-feedback',JSON.stringify(list.slice(-100)))}button.disabled=false});
document.querySelector('#dialog-close').addEventListener('click',()=>document.querySelector('#recipe-dialog').close());
document.querySelector('#dialog-save').addEventListener('click',()=>{if(!activeRecipe)return;if(saved.some(r=>r.id===activeRecipe.id)){toast(ui().already);return}saved.unshift(activeRecipe);writeStorage('good-thyme-saved',JSON.stringify(saved));renderSaved();document.querySelector('#dialog-save').textContent='✓ Saved';toast(ui().saveOk)});
document.querySelector('#recipe-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});
document.querySelector('#helper-form').addEventListener('submit',async e=>{e.preventDefault();if(!activeRecipe)return;const question=document.querySelector('#helper-question').value.trim(),answer=document.querySelector('#helper-answer'),submit=e.currentTarget.querySelector('button');submit.disabled=true;submit.textContent='Thinking…';answer.hidden=false;answer.textContent='Let me think about that…';let usedAI=false,aiUnavailable=false;try{if(location.protocol!=='file:'){const response=await fetch('/api/cooking-help',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,recipe:{name:activeRecipe.name,cuisine:activeRecipe.cuisine,ingredients:activeRecipe.ingredients,steps:activeRecipe.steps,time:activeRecipe.time},language})});if(!response.ok)throw new Error('AI helper unavailable');const data=await response.json();if(!data.answer)throw new Error('Empty answer');answer.textContent=data.answer;usedAI=true}}catch{aiUnavailable=location.protocol!=='file:'}if(!usedAI){answer.textContent=offlineCookingAnswer(activeRecipe,question);document.querySelector('.helper-offline-note').textContent=aiUnavailable?'The AI service is not connected right now; here is an offline answer based on this recipe.':'Offline helper answer based on this recipe’s ingredients and steps.'}else document.querySelector('.helper-offline-note').textContent='Answered by the YourKitchen AI cooking helper.';submit.disabled=false;submit.innerHTML='Ask <span aria-hidden="true">↗</span>'});
document.querySelectorAll('.cuisine').forEach(btn=>btn.addEventListener('click',()=>{cuisine=btn.dataset.cuisine;document.querySelectorAll('.cuisine').forEach(b=>{const active=b===btn;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});renderRecipes()}));
document.querySelectorAll('.mood').forEach(btn=>btn.addEventListener('click',()=>{cuisine='all';document.querySelectorAll('.cuisine').forEach(b=>{const active=b.dataset.cuisine==='all';b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});mood=btn.dataset.mood;document.querySelectorAll('.mood').forEach(b=>{const active=b===btn;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});renderRecipes()}));
document.querySelector('#find-recipes').addEventListener('click',()=>{const query=document.querySelector('#recipe-query').value;clearTimeout(searchSaveTimer);recordSearch(query);renderRecipes();document.querySelector('#results').scrollIntoView({behavior:'smooth',block:'start'})});
document.querySelector('#recipe-query').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const query=e.currentTarget.value;clearTimeout(searchSaveTimer);recordSearch(query);renderRecipes();document.querySelector('#results').scrollIntoView({behavior:'smooth',block:'start'})}});
document.querySelector('#recipe-query').addEventListener('input',e=>{renderRecipes();clearTimeout(searchSaveTimer);const query=e.currentTarget.value;searchSaveTimer=setTimeout(()=>recordSearch(query),650)});
document.querySelector('#refresh').addEventListener('click',renderRecipes);
document.querySelector('#saved-list').addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;const r=saved[Number(btn.dataset.index)];if(btn.classList.contains('copy-saved'))copyIngredients(r);if(btn.classList.contains('remove-saved')){saved.splice(Number(btn.dataset.index),1);writeStorage('good-thyme-saved',JSON.stringify(saved));renderSaved()}});
document.querySelector('#clear-saved').addEventListener('click',()=>{saved=[];writeStorage('good-thyme-saved','[]');renderSaved();toast(ui().clearOk)});
document.querySelector('#clear-search-history').addEventListener('click',()=>{recentSearches=[];writeStorage('yourkitchen-recent-searches','[]');renderForYou();toast('Recent searches cleared from this device.')});
document.querySelector('#feedback-form').addEventListener('submit',async e=>{e.preventDefault();const field=document.querySelector('#feedback-message'),status=document.querySelector('.feedback-note'),button=e.currentTarget.querySelector('button'),message=field.value.trim();if(!message)return;button.disabled=true;status.textContent='Sending your note…';const sent=await deliverFeedback({kind:'site',message},status);if(sent)field.value='';button.disabled=false});
document.querySelector('#account-signup').addEventListener('click',async()=>{const form=document.querySelector('#account-auth-form');form.hidden=!form.hidden;if(!form.hidden){form.elements.email.focus();try{await initializeSupabase()}catch(error){document.querySelector('#account-status').textContent=`Could not connect to Supabase: ${error.message}`}}});
document.querySelector('#account-auth-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=e.submitter,status=document.querySelector('#account-status');button.disabled=true;status.textContent=button.value==='signup'?'Creating your account…':'Signing in…';try{await signInOrCreate(form.elements.email.value.trim(),form.elements.password.value,button.value)}catch(error){status.textContent=error.message||'Sign-in did not work. Please try again.'}finally{button.disabled=false}});
document.querySelector('#account-signout').addEventListener('click',async()=>{if(!supabaseClient)return;const {error}=await supabaseClient.auth.signOut();if(error){document.querySelector('#account-status').textContent=`Could not sign out: ${error.message}`;return}authUser=null;updateAccountAuthUI()});
document.querySelector('#taste-profile-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);tasteProfile={cuisines:data.getAll('cuisine'),spice:String(data.get('spice')||'any')};writeStorage('yourkitchen-taste-profile',JSON.stringify(tasteProfile));renderForYou();document.querySelector('#taste-profile-status').textContent='Saved on this device. Your daily picks will reflect these choices.'});
document.querySelector('#meal-plan-form').addEventListener('submit',e=>{e.preventDefault();const recipe=allKitchenRecipes().find(r=>r.id===document.querySelector('#meal-plan-recipe').value);if(!recipe)return;const date=document.querySelector('#meal-plan-date').value;if(mealPlan.some(item=>item.recipe.id===recipe.id&&item.date===date)){document.querySelector('#meal-plan-recipe').value='';return}mealPlan.push({id:`meal-${Date.now()}`,date,recipe});storePersonalList('yourkitchen-meal-plan',mealPlan);renderMealPlanner()});
document.querySelector('#meal-plan-list').addEventListener('click',e=>{const button=e.target.closest('[data-remove-meal]');if(!button)return;mealPlan=mealPlan.filter(item=>item.id!==button.dataset.removeMeal);storePersonalList('yourkitchen-meal-plan',mealPlan);renderMealPlanner()});
document.querySelector('#make-shopping-list').addEventListener('click',buildShoppingList);
document.querySelector('#shopping-list').addEventListener('change',e=>{const input=e.target.closest('[data-shopping-item]');if(!input)return;const item=shoppingList.find(row=>row.id===input.dataset.shoppingItem);if(item){item.checked=input.checked;writeStorage('yourkitchen-shopping-list',JSON.stringify(shoppingList))}});
document.querySelector('#recent-recipes-list').addEventListener('click',e=>{const button=e.target.closest('[data-history-recipe]');if(button)openRecipe(button.dataset.historyRecipe)});
document.querySelector('#food-lab-history').addEventListener('click',e=>{const button=e.target.closest('[data-history-recipe]');if(button)openRecipe(button.dataset.historyRecipe)});
function renderKitchenChat(){const root=document.querySelector('#kitchen-chat-log');root.innerHTML=kitchenChat.length?kitchenChat.slice(-20).map(item=>`<p class="chat-bubble ${item.role==='user'?'user-bubble':'assistant-bubble'}"></p>`).join(''):'<p class="chat-bubble assistant-bubble">Hi! What are you cooking or curious about today?</p>';root.querySelectorAll('.chat-bubble').forEach((node,index)=>{node.textContent=kitchenChat.slice(-20)[index]?.content||'Hi! What are you cooking or curious about today?'})}
document.querySelector('#kitchen-chat-form').addEventListener('submit',async e=>{e.preventDefault();const field=document.querySelector('#kitchen-chat-question'),question=field.value.trim(),button=e.currentTarget.querySelector('button');if(!question)return;kitchenChat.push({role:'user',content:question});renderKitchenChat();storePersonalList('yourkitchen-chat',kitchenChat);field.value='';button.disabled=true;button.textContent='Thinking…';let answer='';try{if(location.protocol==='file:')throw new Error('Offline');const response=await fetch('/api/cooking-help',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:'general',question,language,preferences:tasteProfile,recentRecipes:recentRecipes.slice(0,5).map(r=>r.name)})}),data=await response.json();if(!response.ok||!data.answer)throw new Error(data.error||'The kitchen companion is unavailable.');answer=data.answer}catch{answer=/substitut|instead of|replace/i.test(question)?'A good substitution depends on the recipe. Tell me which ingredient and dish, and I can suggest a closer swap when the AI kitchen companion is online.':/leftover|left over/i.test(question)?'Try building a quick bowl: add a grain or bread, something fresh, and a bright sauce. When the hosted kitchen companion is online, I can tailor ideas to your ingredients.':'I’m here to help with cooking, meal ideas, and ingredient swaps. The full AI companion is available when YourKitchen is hosted and its AI service is connected.'}kitchenChat.push({role:'assistant',content:answer});kitchenChat=kitchenChat.slice(-30);renderKitchenChat();storePersonalList('yourkitchen-chat',kitchenChat);button.disabled=false;button.textContent='Ask ↗'});
const foodQuestions=[{q:'Which herb gives pesto its classic fresh, peppery flavour?',options:['Basil','Coriander','Mint'],answer:'Basil'},{q:'What makes bread dough rise?',options:['Yeast','Cocoa','Vinegar'],answer:'Yeast'},{q:'Which ingredient gives hummus its creamy base?',options:['Chickpeas','Lentils','Green peas'],answer:'Chickpeas'},{q:'What is the main ingredient in guacamole?',options:['Avocado','Cucumber','Green pepper'],answer:'Avocado'},{q:'Which spice is known for its golden colour?',options:['Turmeric','Cinnamon','Black pepper'],answer:'Turmeric'}];let currentFoodQuestion=foodQuestions[0];
function showFoodQuestion(question){currentFoodQuestion=question;document.querySelector('#game-question').textContent=question.q;document.querySelector('#game-options').innerHTML=question.options.map(option=>`<button type="button" data-answer="${escapeHTML(option)}">${escapeHTML(option)}</button>`).join('');document.querySelector('#game-status').textContent='Pick your answer!'}
document.querySelector('#game-score').textContent=gameScore;document.querySelector('#game-options').addEventListener('click',e=>{const button=e.target.closest('[data-answer]');if(!button||button.disabled)return;document.querySelectorAll('#game-options button').forEach(option=>option.disabled=true);if(button.dataset.answer===currentFoodQuestion.answer){gameScore++;writeStorage('yourkitchen-game-score',String(gameScore));document.querySelector('#game-score').textContent=gameScore;document.querySelector('#game-status').textContent='That’s right! Nice kitchen instincts.';button.classList.add('game-correct')}else{document.querySelector('#game-status').textContent=`Not quite — it’s ${currentFoodQuestion.answer}. Try another!`;button.classList.add('game-wrong')}});
document.querySelector('#new-food-question').addEventListener('click',()=>{const choices=foodQuestions.filter(q=>q!==currentFoodQuestion);showFoodQuestion(choices[Math.floor(Math.random()*choices.length)])});
const sectionPages={top:'home',workbench:'explore',results:'explore',vegan:'vegan',saved:'favorites','for-you':'for-you','community-recipes':'community',ai:'ai','food-lab':'food-lab',dashboard:'dashboard',account:'you',how:'home'};
function showPage(page,{updateHistory=true}={}){const valid=['home','explore','vegan','favorites','for-you','community','ai','food-lab','dashboard','you'];if(!valid.includes(page))page='home';document.body.dataset.page=page;if(page==='for-you')renderForYou();if(page==='vegan')renderVeganRecipes();if(page==='community')loadCommunityFeed();document.querySelectorAll('.bottom-nav a[data-page]').forEach(link=>{if(link.dataset.page===page)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')});if(updateHistory){const link=document.querySelector(`.bottom-nav a[data-page="${page}"]`);if(link&&location.hash!==link.getAttribute('href'))history.pushState({page},'',link.getAttribute('href'))}window.scrollTo({top:0,behavior:'smooth'})}
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#"]');if(!link)return;const target=link.getAttribute('href').slice(1);const page=link.dataset.page||sectionPages[target];if(!page)return;e.preventDefault();showPage(page)});
window.addEventListener('popstate',()=>showPage(sectionPages[location.hash.slice(1)]||'home',{updateHistory:false}));
